        # axis='h': runs along a top/bottom row; axis='v': along left/right column
        n = w if axis == 'h' else h
        vals = [grid[fixed][i] if axis == 'h' else grid[i][fixed] for i in range(n)]
        res, i = [], 0
        while i < n:
            j = i + 1
            while j < n and vals[j] == vals[i]:
                j += 1
            if vals[i] != bg and j-i >= 2:
                res.append((vals[i], i, j-1))
            i = j
        return res

    def process_pair(axis, first_side, run1, run2):
        color, a, b = run1
        color2, c, d = run2
        if color != color2 or b-a != d-c:
            return
